import json,re
d=json.load(open('typo.json'))
out=[]
def walk(o):
    if isinstance(o,dict):
        if o.get('type')=='text' and 'text' in o: out.append(o['text'])
        elif o.get('type')=='codeVoice' and 'code' in o: out.append('\`'+o['code']+'\`')
        elif o.get('type')=='heading' and 'text' in o: out.append('\n\n## '+o['text']+'\n')
        elif o.get('type')=='paragraph': out.append('\n')
        for v in o.values(): walk(v)
    elif isinstance(o,list):
        for v in o: walk(v)
walk(d)
t=' '.join(out)
t=re.sub(r' +',' ',t)
open('typo.txt','w').write(t)
